        "Follow",
        foreign_keys=[Follow.followed_id],
        backref=db.backref("followed", lazy="joined"),
        lazy="dynamic",
        cascade="all, delete-orphan",
    )
    comments = db.relationship("Comment", backref="author", lazy="dynamic")

    @staticmethod
    def add_self_follows():
        for user in User.query.all():
            if not user.is_following(user):
                user.follow(user)
                db.session.add(user)
                db.session.commit()

    def __init__(self, **kwargs):
        super(User, self).__init__(**kwargs)
        if self.role is None and current_app:
            admin_email = current_app.config.get("FLASKY_ADMIN")
            if self.email == admin_email:
                self.role = Role.query.filter_by(name="Administrator").first()
            if self.role is None:
                self.role = Role.query.filter_by(default=True).first()
        if self.email is not None and self.avatar_hash is None:
            self.avatar_hash = self.gravatar_hash()
        self.follow(self)

    @property
    def password(self):
        raise AttributeError("password is not a readable attribute")

    @password.setter
    def password(self, password):
        self.password_hash = generate_password_hash(password)

    def verify_password(self, password):
        return check_password_hash(self.password_hash, password)

    @staticmethod
    def _serializer(expiration=None, expires_in=None):
        if expires_in is not None:
            return Serializer(current_app.config["SECRET_KEY"], expires_in=expires_in)
        if expiration is not None:
            return Serializer(current_app.config["SECRET_KEY"], expiration)
        return Serializer(current_app.config["SECRET_KEY"])

    @staticmethod
    def _loads_token(token, expiration=None):
        serializer = User._serializer(expiration=expiration)
        if isinstance(token, str):
            token = token.encode("utf-8")
        return serializer.loads(token)

    def generate_confirmation_token(self, expiration=3600):
        serializer = self._serializer(expiration=expiration)
        return serializer.dumps({"confirm": self.id}).decode("utf-8")

    def confirm(self, token):
        try:
            data = self._loads_token(token)
        except Exception:
            return False
        if data.get("confirm") != self.id:
            return False
        self.confirmed = True
        db.session.add(self)
        return True

    def generate_reset_token(self, expiration=3600):
        serializer = self._serializer(expiration=expiration)
        return serializer.dumps({"reset": self.id}).decode("utf-8")

    @staticmethod
    def reset_password(token, new_password):
        try:
            data = User._loads_token(token)
        except Exception:
            return False
        user = User.query.get(data.get("reset"))
        if user is None:
            return False
        user.password = new_password
        db.session.add(user)
        return True

    def generate_email_change_token(self, new_email, expiration=3600):
        serializer = self._serializer(expiration=expiration)
        return serializer.dumps(
            {"change_email": self.id, "new_email": new_email}
        ).decode("utf-8")

    def change_email(self, token):
        try:
            data = self._loads_token(token)
        except Exception:
            return False
        if data.get("change_email") != self.id:
            return False
        new_email = data.get("new_email")
        if new_email is None:
            return False
        if self.query.filter_by(email=new_email).first() is not None:
            return False
        self.email = new_email
        self.avatar_hash = self.gravatar_hash()
        db.session.add(self)
        return True

    def can(self, perm):
        return self.role is not None and self.role.has_permission(perm)

    def is_administrator(self):
        return self.can(Permission.ADMIN)

    def ping(self):
        self.last_seen = datetime.utcnow()
        db.session.add(self)

    def gravatar_hash(self):
        return hashlib.md5(self.email.lower().encode("utf-8")).hexdigest()

    def gravatar(self, size=100, default="identicon", rating="g"):
        url = "https://secure.gravatar.com/avatar"
        avatar_hash = self.avatar_hash or self.gravatar_hash()
        return "{url}/{hash}?s={size}&d={default}&r={rating}".format(
            url=url,
            hash=avatar_hash,
            size=size,
            default=default,
            rating=rating,
        )

    def follow(self, user):
        if not self.is_following(user):
            db.session.add(Follow(follower=self, followed=user))

    def unfollow(self, user):
        follow = self.followed.filter_by(followed_id=user.id).first()
        if follow:
            db.session.delete(follow)

    def is_following(self, user):
        if user is None or user.id is None:
            return False
        return self.followed.filter_by(followed_id=user.id).first() is not None

    def is_followed_by(self, user):
        if user is None or user.id is None:
            return False
        return self.followers.filter_by(follower_id=user.id).first() is not None

    @property
    def followed_posts(self):
        return Post.query.join(Follow, Follow.followed_id == Post.author_id).filter(
            Follow.follower_id == self.id
        )

    def to_json(self):
        return {
            "url": url_for("api.get_user", id=self.id),
            "username": self.username,
            "member_since": self.member_since,
            "last_seen": self.last_seen,
            "posts_url": url_for("api.get_user_posts", id=self.id),
            "followed_posts_url": url_for("api.get_user_followed_posts", id=self.id),
            "post_count": self.posts.count(),
        }

    def generate_auth_token(self, expiration):
        serializer = self._serializer(expires_in=expiration)
        return serializer.dumps({"id": self.id}).decode("utf-8")

    @staticmethod
    def verify_auth_token(token):
        try:
            data = User._loads_token(token)
        except Exception:
            return None
        return User.query.get(data["id"])

    def __repr__(self):
        return "<User %r>" % self.username


