from flask import current_app, g, jsonify, request, url_for

from . import api
from .decorators import permission_required
from .errors import forbidden
from .. import db
from ..models import Permission, Post


@api.route("/posts/")
def get_posts():
    page = request.args.get("page", 1, type=int)
    pagination = Post.query.paginate(
        page=page,
        per_page=current_app.config["FLASKY_POSTS_PER_PAGE"],
        error_out=False,
    )
    posts = pagination.items
    prev = url_for("api.get_posts", page=page - 1) if pagination.has_prev else None
    next = url_for("api.get_posts", page=page + 1) if pagination.has_next else None
    return jsonify(
        {
            "posts": [post.to_json() for post in posts],
            "prev": prev,
            "next": next,
            "count": pagination.total,
        }
    )


@api.route("/posts/<int:id>")
def get_post(id):
    post = Post.query.get_or_404(id)
    return jsonify(post.to_json())


@api.route("/posts/", methods=["POST"])
@permission_required(Permission.WRITE)
def new_post():
    post = Post.from_json(request.get_json(silent=True))
    post.author = g.current_user
    db.session.add(post)
    db.session.commit()
    return jsonify(post.to_json()), 201, {"Location": url_for("api.get_post", id=post.id)}


@api.route("/posts/<int:id>", methods=["PUT"])
@permission_required(Permission.WRITE)
def edit_post(id):
    post = Post.query.get_or_404(id)
    if g.current_user != post.author and not g.current_user.can(Permission.ADMIN):
        return forbidden("Insufficient permissions")
    payload = request.get_json(silent=True) or {}
    post.body = payload.get("body", post.body)
    db.session.add(post)
    db.session.commit()
    return jsonify(post.to_json())


@api.route("/posts/<int:id>", methods=["DELETE"])
@permission_required(Permission.WRITE)
def delete_post(id):
    post = Post.query.get_or_404(id)
    if g.current_user != post.author and not g.current_user.can(Permission.ADMIN):
        return forbidden("Insufficient permissions")
    db.session.delete(post)
    db.session.commit()
    return "", 204

