/workspace/app/templates/_macros.html.content:
{% macro pagination_widget(pagination, endpoint) %}
<ul class="pagination">
    {% if pagination.has_prev %}
    <li class="prev">
        <a href="{{ url_for(endpoint, page=pagination.prev_num, **kwargs) }}">&laquo; Previous</a>
    </li>
    {% else %}
    <li class="prev disabled"><a href="#">&laquo; Previous</a></li>
    {% endif %}
    {% for p in pagination.iter_pages() %}
        {% if p %}
            {% if p == pagination.page %}
            <li class="active"><a href="{{ url_for(endpoint, page=p, **kwargs) }}">{{ p }}</a></li>
            {% else %}
            <li><a href="{{ url_for(endpoint, page=p, **kwargs) }}">{{ p }}</a></li>
            {% endif %}
        {% else %}
        <li class="disabled"><a href="#">&hellip;</a></li>
        {% endif %}
    {% endfor %}
    {% if pagination.has_next %}
    <li class="next">
        <a href="{{ url_for(endpoint, page=pagination.next_num, **kwargs) }}">Next &raquo;</a>
    </li>
    {% else %}
    <li class="next disabled"><a href="#">Next &raquo;</a></li>
    {% endif %}
</ul>
{% endmacro %}

